package com.nattechnologies.trastcms.plugins.pay.cleanpay;
import org.springframework.beans.factory.annotation.Value;import org.springframework.context.ApplicationContext;import org.springframework.stereotype.Component;import javax.crypto.*;import javax.crypto.spec.*;import java.lang.reflect.Method;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;
@Component public class CleanPaySecretCodec{private final ApplicationContext context;private final String fallbackKey;public CleanPaySecretCodec(ApplicationContext c,@Value("${trastcms.security.secret:${TRASTCMS_SECRET_KEY:}}")String key){context=c;fallbackKey=key;}
public String encrypt(String value){if(value==null||value.isBlank())return null;String delegated=delegate("encrypt",value);if(delegated!=null)return "bean:"+delegated;if(fallbackKey.isBlank())throw new IllegalStateException("Configure TRASTCMS_SECRET_KEY before saving the CleanPay token");try{byte[] iv=new byte[12];new SecureRandom().nextBytes(iv);Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key(),new GCMParameterSpec(128,iv));byte[] encrypted=cipher.doFinal(value.getBytes(StandardCharsets.UTF_8));return "aes:"+Base64.getEncoder().encodeToString(iv)+":"+Base64.getEncoder().encodeToString(encrypted);}catch(Exception e){throw new IllegalStateException("Token encryption failed",e);}}
public String decrypt(String value){if(value==null||value.isBlank())return null;if(value.startsWith("bean:")){String d=delegate("decrypt",value.substring(5));if(d!=null)return d;throw new IllegalStateException("Configured encryption service is unavailable");}if(!value.startsWith("aes:"))throw new IllegalStateException("Unsupported token encoding");try{String[] p=value.split(":",3);byte[] iv=Base64.getDecoder().decode(p[1]),enc=Base64.getDecoder().decode(p[2]);Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,iv));return new String(cipher.doFinal(enc),StandardCharsets.UTF_8);}catch(Exception e){throw new IllegalStateException("Token decryption failed",e);}}
private SecretKeySpec key()throws Exception{byte[] hash=MessageDigest.getInstance("SHA-256").digest(fallbackKey.getBytes(StandardCharsets.UTF_8));return new SecretKeySpec(hash,"AES");}
private String delegate(String method,String value){for(String n:context.getBeanDefinitionNames())try{Object bean=context.getBean(n);String cn=bean.getClass().getName().toLowerCase();if(!(cn.contains("crypto")||cn.contains("encrypt")||cn.contains("cipher")||cn.contains("secret"))||bean==this)continue;for(Method m:bean.getClass().getMethods())if(m.getName().equals(method)&&m.getParameterCount()==1&&m.getParameterTypes()[0]==String.class&&m.getReturnType()==String.class)return(String)m.invoke(bean,value);}catch(Exception ignored){}return null;}}
